WITH canon AS MATERIALIZED(SELECT v.session_date,v.company_ordinal,to_jsonb(v)::text consumer_text,to_jsonb(p)::text base_point_text FROM population_top3000_202608_202609_v1.working_d02_dated_source_points_v2 v JOIN population_top3000_202608_202609_v1.d02_anchor_source_point_v2 p USING(session_date,company_ordinal)WHERE v.session_date IN(DATE'__DATE_1__',DATE'__DATE_2__')), hashed AS MATERIALIZED(SELECT *,encode(sha256(convert_to(consumer_text,'UTF8')),'hex')consumer_sha256,encode(sha256(convert_to(base_point_text,'UTF8')),'hex')base_point_sha256 FROM canon),checked AS MATERIALIZED(SELECT population_top3000_202608_202609_v1.ctx06_aug03_check_v5(count(*)=6000 AND count(DISTINCT(session_date,company_ordinal))=6000 AND count(DISTINCT session_date)=2,'D02_EXPORT_EXACT_TWO_DATES_6000')ok FROM hashed)
SELECT jsonb_build_object('kind','D02_CONSUMER_CANONICAL_CHUNK_V1','chunk_index',__CHUNK_INDEX__,'row_count',count(*),'dates',jsonb_build_array('__DATE_1__','__DATE_2__'),'ordered_consumer_row_sha_manifest',encode(sha256(convert_to(string_agg(consumer_sha256,E'\n'ORDER BY session_date,company_ordinal),'UTF8')),'hex'),'records',jsonb_agg(jsonb_build_object('consumer_text',consumer_text,'consumer_sha256',consumer_sha256,'base_point_text',base_point_text,'base_point_sha256',base_point_sha256)ORDER BY session_date,company_ordinal))export FROM hashed CROSS JOIN checked WHERE checked.ok;COMMIT;
